var lastRemaining = function(n) {
    let head = 1, step = 1, remaining = n;
    let leftToRight = true;
    while (remaining > 1) {
        if (leftToRight || remaining % 2 === 1) {
            head += step;
        }
        remaining = Math.floor(remaining / 2);
        step *= 2;
        leftToRight = !leftToRight;
    }
    return head;
};
